var p = new Person("Alice", 30);
Console.WriteLine($"{{{p.Name} {p.Age}}}");

record Person(string Name, int Age);

var p = new Point(5, 10);
p = p with { Y = 20 };
Console.WriteLine($"{{{p.X} {p.Y}}}");

record Point(int X, int Y);

var book = new Book("Go Programming");
Console.WriteLine($"{{{book.Title}  {book.Pages}}}");

record Book(string Title, string Author = "", int Pages = 0);

var emp = new Employee(new Person("Bob"), "Acme");
Console.WriteLine(emp.Company);

record Person(string Name);
record Employee(Person Person, string Company);

var r = new Rectangle(0, 0);
Console.WriteLine($"{{{r.Width} {r.Height}}}");

record Rectangle(double Width, double Height);

var a = new Config("localhost", 8080);
var b = new Config("localhost", 8080);
Console.WriteLine(a == b ? "true" : "false");

record Config(string Host, int Port);

var c = new Counter();
c = c with { Value = c.Value + 5 };
Console.WriteLine(c.Value);

record Counter(int Value = 0);
